svg.script:
const links = [
    'https://ongoingeducation.online',
    'https://exam.sourcescs.com',
    'https://mzu.educationalhelpus.online',
    'https://work.readywintersprings.org',
    'https://reading.dailey1.net',
    'https://calc.genovia.ro',
    'https://anatomy.medscience.cl',
    'https://preposteroustomato.myk.sh',
    'https://tomato.n43.pw',
    'https://cdn.jsdelivr.net/gh/taiigo/mizumath/index.svg'
];

async function findlink() {
    for (const link of links) {
        try {
            const res = await fetch(`${link}/api/check/`, {
                cache: 'no-store',
                signal: AbortSignal.timeout(3000)
            });

            if (res.ok && (await res.text()).trim() === 'works') {
                location.replace(link);
                return;
            }
        } catch {}
    }

    document.getElementById('status').textContent = 'failed to find link join discord.gg/uncensor';
}

findlink();
